INSERT INTO `cursos` (`id`,`nome`,`subtitulo`,`descricao`,`nivel`,`duracao`,`numero_aulas`,`preco`,`idioma`,`instrutor`,`alunos_matriculados`,`imagem_url`,`ultima_atualizacao`,`slug`) VALUES (1,'Java completo: do básico ao avançado','Bem vindo ao Curso mais completo de java do mercado, com OO, UML, JDBC, Spring, JPA e muito mais!','\n## Bem-vindo ao curso mais completo de Java do mercado\n\nCom Programação Orientada a Objetos, UML, JDBC, Spring Boot, JPA, APIs REST, arquitetura de software e muito mais...\n\nJava continua sendo uma das linguagens mais utilizadas do mundo. Grandes empresas, bancos, sistemas corporativos e APIs modernas utilizam Java diariamente para construir soluções robustas, escaláveis e seguras.\n\n---\n\n#### O que você vai aprender\n\n- Dominar os fundamentos avançados da linguagem Java\n- Trabalhar com Programação Orientada a Objetos na prática\n- Modelar sistemas utilizando UML e boas práticas de arquitetura\n- Criar aplicações conectadas a banco de dados com JDBC\n- Desenvolver APIs REST profissionais com Spring Boot\n- Trabalhar com JPA e Hibernate para persistência de dados\n- Implementar autenticação, validações e boas práticas de segurança\n- Construir um portfólio completo com projetos profissionais\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores que já conhecem lógica ou Java básico e querem evoluir\n- Programadores que desejam entrar no mercado Java profissional\n- Estudantes que querem aprender backend moderno com Spring Boot\n- Profissionais que desejam fortalecer conhecimentos em arquitetura e banco de dados\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de desenvolver aplicações Java completas utilizando tecnologias modernas do ecossistema Spring, criando APIs profissionais, conectando bancos de dados e aplicando boas práticas utilizadas no mercado.\n','Todos os níveis','16.66',41,399.99,'Português','Gustavo Santos',5000,'v1779370131/java-image_tpbisa.jpg','2026-04-24 00:00:00.000000','java-completo'),
(2,'Java Spring Boot completo','Crie APIs REST modernas com Spring Boot, JPA e segurança JWT','\n## Bem-vindo ao curso mais completo de Spring Boot do mercado\n\nCom APIs REST, JPA, segurança com JWT, boas práticas e arquitetura profissional de backend moderno.\n\nSpring Boot é o framework Java mais utilizado por empresas para construir APIs escaláveis, seguras e prontas para produção.\n\n---\n\n#### O que você vai aprender\n\n- Criar APIs REST completas com Spring Boot\n- Trabalhar com JPA e Hibernate para persistência de dados\n- Implementar autenticação e autorização com JWT\n- Estruturar projetos seguindo padrões utilizados no mercado\n- Aplicar boas práticas de Clean Code e arquitetura em camadas\n- Integrar banco de dados relacionais com Spring Data\n- Documentar APIs com Swagger/OpenAPI\n- Construir um portfólio backend profissional\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores Java que querem dominar Spring Boot\n- Programadores que desejam criar APIs profissionais\n- Estudantes que querem aprender backend moderno e seguro\n- Profissionais que buscam evoluir para arquiteturas escaláveis\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de criar APIs REST completas, seguras e bem estruturadas com Spring Boot, prontas para o mercado de trabalho e para projetos reais.\n','Intermediário','180',55,189.99,'Português','Carlos Silva',1200,'v1779370131/spring_bajo7x.jpg','2026-04-20 00:00:00.000000','java-spring-boot'),
(3,'React do zero ao avançado','Aprenda React com hooks, context API e projetos reais','\n## Bem-vindo ao curso mais completo de React do mercado\n\nCom Hooks, Context API, roteamento, consumo de APIs e projetos reais do básico ao avançado.\n\nReact é a biblioteca JavaScript mais utilizada no mundo para construção de interfaces modernas, reativas e performáticas.\n\n---\n\n#### O que você vai aprender\n\n- Dominar os fundamentos do React com componentes e props\n- Trabalhar com Hooks: useState, useEffect, useContext e mais\n- Gerenciar estado global com Context API e Reducers\n- Criar rotas e navegação com React Router\n- Consumir APIs REST e trabalhar com dados assíncronos\n- Aplicar boas práticas de organização e componentização\n- Construir interfaces responsivas e modernas\n- Desenvolver projetos reais para seu portfólio\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores JavaScript que querem aprender React\n- Programadores que desejam criar interfaces modernas\n- Estudantes que querem entrar no mercado frontend\n- Profissionais que buscam evoluir com uma das tecnologias mais exigidas do mercado\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de construir aplicações React completas, organizadas e performáticas, prontas para produção e para o mercado de trabalho.\n','Intermediário','150',50,179.99,'Português','Mariana Souza',2100,'v1779370133/react-image_zpb6mp.jpg','2026-04-18 00:00:00.000000','react-do-zero'),
(4,'JavaScript moderno (ES6+)','Domine JS moderno com práticas usadas no mercado','\n## Bem-vindo ao curso mais completo de JavaScript Moderno do mercado\n\nCom ES6+, manipulação do DOM, assincronismo, módulos e as práticas mais exigidas pelo mercado.\n\nJavaScript é a linguagem da web. Dominar seus recursos modernos é essencial para qualquer desenvolvedor que deseja criar aplicações profissionais e eficientes.\n\n---\n\n#### O que você vai aprender\n\n- Dominar os fundamentos e recursos modernos do ES6+\n- Trabalhar com arrow functions, destructuring e spread operator\n- Entender escopo, closures e o modelo de execução do JS\n- Trabalhar com Promises, async/await e requisições HTTP\n- Manipular o DOM de forma eficiente\n- Organizar código com módulos e boas práticas\n- Entender orientação a objetos com classes no JavaScript\n- Construir projetos práticos para o portfólio\n\n---\n\n#### Para quem é este curso?\n\n- Iniciantes que querem aprender JavaScript do jeito certo\n- Desenvolvedores que querem consolidar e modernizar seus conhecimentos\n- Estudantes que desejam entrar no desenvolvimento web\n- Profissionais que querem dominar JS antes de partir para frameworks\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você dominará JavaScript moderno e estará preparado para trabalhar com qualquer framework ou biblioteca do ecossistema JS, com código limpo e profissional.\n','Básico','120',45,149.99,'Português','Lucas Ferreira',3000,'v1779370132/javascript-image_dgxugp.jpg','2026-04-15 00:00:00.000000','javascript-moderno'),
(5,'HTML e CSS na prática','Crie sites responsivos do zero com boas práticas','\n## Bem-vindo ao curso mais completo de HTML e CSS do mercado\n\nCom layouts modernos, Flexbox, Grid, responsividade e boas práticas de desenvolvimento web.\n\nHTML e CSS são a base de tudo na web. Dominar essas tecnologias é o primeiro passo para criar interfaces bonitas, acessíveis e responsivas.\n\n---\n\n#### O que você vai aprender\n\n- Estruturar páginas web semânticas com HTML5\n- Estilizar interfaces modernas com CSS3\n- Dominar Flexbox e Grid para layouts responsivos\n- Criar designs adaptáveis para mobile, tablet e desktop\n- Aplicar boas práticas de acessibilidade e SEO básico\n- Trabalhar com animações e transições CSS\n- Utilizar variáveis CSS e boas práticas de organização\n- Construir projetos reais para o portfólio\n\n---\n\n#### Para quem é este curso?\n\n- Completos iniciantes que querem entrar no desenvolvimento web\n- Designers que desejam aprender a codar suas interfaces\n- Estudantes que querem construir uma base sólida em frontend\n- Profissionais que desejam melhorar suas habilidades em CSS moderno\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de criar páginas web completas, responsivas e visualmente profissionais, com domínio total sobre HTML semântico e CSS moderno.\n','Básico','100',40,99.99,'Português','Ana Costa',5000,'v1779370133/html-css-image_ehwzte.jpg','2026-04-10 00:00:00.000000','html-css-pratica'),
(6,'Node.js e APIs REST','Desenvolva APIs completas com Node, Express e MongoDB','\n## Bem-vindo ao curso mais completo de Node.js do mercado\n\nCom Express, MongoDB, APIs REST, autenticação e arquitetura de backend moderno e escalável.\n\nNode.js revolucionou o desenvolvimento backend ao permitir JavaScript no servidor. É uma das tecnologias mais exigidas por empresas que buscam performance e escalabilidade.\n\n---\n\n#### O que você vai aprender\n\n- Dominar Node.js e seu modelo assíncrono baseado em eventos\n- Criar APIs REST completas com Express.js\n- Trabalhar com MongoDB e Mongoose para persistência de dados\n- Implementar autenticação com JWT e boas práticas de segurança\n- Estruturar projetos backend com arquitetura profissional\n- Trabalhar com middlewares, rotas e tratamento de erros\n- Fazer upload de arquivos e integrar serviços externos\n- Construir um portfólio backend completo\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores JavaScript que querem atuar no backend\n- Programadores que desejam criar APIs modernas com Node\n- Estudantes que querem aprender backend com JavaScript\n- Profissionais que buscam uma stack completa JS fullstack\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de desenvolver APIs REST completas, seguras e escaláveis com Node.js, Express e MongoDB, prontas para produção e para o mercado de trabalho.\n','Intermediário','160',52,169.99,'Português','Rafael Lima',1800,'v1779370132/node-js-image_f2mlox.jpg','2026-04-12 00:00:00.000000','node-js-api-rest'),
(7,'Banco de Dados com MySQL','Modelagem, queries e performance com MySQL','\n## Bem-vindo ao curso mais completo de MySQL do mercado\n\nCom modelagem de dados, queries avançadas, índices, performance e boas práticas de banco de dados relacional.\n\nMySQL é o banco de dados relacional mais utilizado no mundo. Dominar SQL é uma habilidade essencial para qualquer desenvolvedor backend ou analista de dados.\n\n---\n\n#### O que você vai aprender\n\n- Entender os fundamentos de banco de dados relacionais\n- Criar e modelar tabelas, relacionamentos e chaves estrangeiras\n- Escrever queries SQL do básico ao avançado\n- Trabalhar com JOINs, subqueries e funções agregadas\n- Otimizar performance com índices e análise de queries\n- Aplicar transações, procedures e triggers\n- Modelar sistemas reais com boas práticas de normalização\n- Integrar MySQL com aplicações backend\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores que precisam dominar banco de dados relacional\n- Analistas que desejam escrever queries mais eficientes\n- Estudantes que querem aprender SQL do jeito certo\n- Profissionais que buscam melhorar a performance de suas aplicações\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de modelar, consultar e otimizar bancos de dados MySQL com confiança, aplicando boas práticas utilizadas em sistemas reais e corporativos.\n','Básico','110',38,129.99,'Português','Fernanda Alves',2500,'v1779374544/SQL-image_cnmgbw.jpg','2026-04-08 00:00:00.000000','mysql-database'),
(8,'Python para análise de dados','Pandas, NumPy e visualização de dados','\n## Bem-vindo ao curso mais completo de Python para Dados do mercado\n\nCom Pandas, NumPy, Matplotlib, análise exploratória e projetos reais de ciência de dados.\n\nPython é a linguagem número um para análise de dados e ciência de dados. Dominar suas bibliotecas é essencial para quem quer trabalhar com dados no mercado.\n\n---\n\n#### O que você vai aprender\n\n- Dominar Python aplicado à manipulação e análise de dados\n- Trabalhar com Pandas para limpeza e transformação de dados\n- Utilizar NumPy para computação numérica eficiente\n- Criar visualizações profissionais com Matplotlib e Seaborn\n- Realizar análise exploratória de dados (EDA) completa\n- Trabalhar com arquivos CSV, Excel e bancos de dados\n- Aplicar estatística básica na análise de dados reais\n- Construir projetos de análise para o portfólio\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores que querem migrar para a área de dados\n- Analistas que desejam automatizar e melhorar suas análises\n- Estudantes que querem entrar em ciência de dados\n- Profissionais que buscam trabalhar com Python no dia a dia\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de realizar análises de dados completas com Python, desde a coleta e limpeza até a visualização e interpretação dos resultados, com projetos reais no portfólio.\n','Intermediário','140',48,159.99,'Português','João Mendes',3200,'v1779370133/python-image_kb7uyx.jpg','2026-04-14 00:00:00.000000','python-data'),
(9,'Git e GitHub completo','Controle de versão do básico ao avançado','\n## Bem-vindo ao curso mais completo de Git e GitHub do mercado\n\nCom controle de versão, fluxo profissional, branches, pull requests e boas práticas utilizadas por times reais.\n\nGit é a ferramenta de controle de versão mais utilizada no mundo. Dominar Git e GitHub é indispensável para qualquer desenvolvedor que trabalha em equipe ou em projetos reais.\n\n---\n\n#### O que você vai aprender\n\n- Entender como o Git funciona internamente\n- Criar e gerenciar repositórios locais e remotos\n- Trabalhar com branches, merges e resolução de conflitos\n- Utilizar o fluxo profissional com pull requests e code review\n- Aplicar Git Flow e estratégias de branching para times\n- Trabalhar com tags, stash e rebase\n- Integrar GitHub com projetos e pipelines de CI/CD\n- Colaborar em projetos open source com boas práticas\n\n---\n\n#### Para quem é este curso?\n\n- Iniciantes que nunca usaram controle de versão\n- Desenvolvedores que usam Git superficialmente e querem dominar\n- Estudantes que querem trabalhar de forma profissional em equipe\n- Profissionais que desejam melhorar seu fluxo de trabalho com Git\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você terá domínio completo sobre Git e GitHub, trabalhando com confiança em projetos individuais e em equipe, seguindo o fluxo profissional utilizado por times no mercado.\n','Básico','60',5,79.99,'Português','Bruno Rocha',4000,'v1779370131/git-image_qdclen.png','2026-04-05 00:00:00.000000','git-github'),
(10,'Desenvolvimento Mobile com Flutter','Crie apps nativos para Android e iOS','\n## Bem-vindo ao curso mais completo de Flutter do mercado\n\nCom widgets, navegação, estado, consumo de APIs e projetos reais para Android e iOS.\n\nFlutter é o framework do Google para criação de aplicativos nativos multiplataforma. Com uma única base de código, você cria apps para Android, iOS, web e desktop.\n\n---\n\n#### O que você vai aprender\n\n- Dominar os fundamentos do Flutter e da linguagem Dart\n- Trabalhar com widgets, layouts e componentes visuais\n- Gerenciar estado com Provider, Riverpod ou Bloc\n- Criar navegação e roteamento entre telas\n- Consumir APIs REST e trabalhar com dados assíncronos\n- Integrar banco de dados local com SQLite ou Hive\n- Publicar aplicativos na Play Store e App Store\n- Construir projetos reais para o portfólio mobile\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores que querem entrar no mercado mobile\n- Programadores que desejam criar apps para Android e iOS\n- Estudantes que querem aprender desenvolvimento multiplataforma\n- Profissionais que buscam expandir suas habilidades para mobile\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de desenvolver aplicativos mobile completos com Flutter, desde a interface até a integração com APIs e banco de dados, prontos para publicação nas lojas.\n','Intermediário','170',58,189.99,'Português','Juliana Martins',1500,'v1779370131/flutter-image_q0giwr.jpg','2026-04-16 00:00:00.000000','mobile-flutter-dev'),
(11,'UX/UI Design para devs','Fundamentos de design para interfaces modernas','\n## Bem-vindo ao curso mais completo de UX/UI Design para Desenvolvedores\n\nCom fundamentos de design, prototipação, Figma, usabilidade e boas práticas para criar interfaces profissionais.\n\nUX/UI Design é uma habilidade cada vez mais valorizada no mercado. Desenvolvedores que entendem de design entregam produtos melhores e se destacam nas equipes.\n\n---\n\n#### O que você vai aprender\n\n- Entender os princípios fundamentais de UX e UI\n- Trabalhar com tipografia, cores, espaçamento e hierarquia visual\n- Criar wireframes e protótipos com Figma\n- Aplicar heurísticas de usabilidade de Nielsen\n- Desenvolver interfaces acessíveis e inclusivas\n- Criar design systems e componentes reutilizáveis\n- Conduzir testes de usabilidade básicos\n- Melhorar a experiência do usuário nos seus projetos\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores que querem criar interfaces mais profissionais\n- Programadores que desejam entender o processo de design\n- Estudantes que querem agregar design às suas habilidades técnicas\n- Profissionais que trabalham com produto e desejam melhorar o UX\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de projetar interfaces modernas, acessíveis e centradas no usuário, aplicando conceitos de UX/UI no seu dia a dia como desenvolvedor.\n','Básico','90',30,119.99,'Português','Camila Duarte',900,'v1779370132/UX-image_q4vnoi.jpg','2026-04-09 00:00:00.000000','ui-ux-4devs'),
(13,'AWS Completo: do Básico ao Avançado','Domine a Amazon Web Services com EC2, S3, Lambda, RDS, IAM e muito mais!','\n## Bem-vindo ao curso mais completo de AWS do mercado\n\nCom EC2, S3, Lambda, RDS, IAM, CloudFront, infraestrutura como código e arquiteturas profissionais na nuvem.\n\nA Amazon Web Services é a plataforma de nuvem mais utilizada no mundo. Dominar AWS é uma das habilidades mais valorizadas e bem remuneradas do mercado de tecnologia.\n\n---\n\n#### O que você vai aprender\n\n- Entender os fundamentos de computação em nuvem com AWS\n- Criar e gerenciar instâncias EC2 e grupos de auto scaling\n- Armazenar e distribuir arquivos com S3 e CloudFront\n- Desenvolver funções serverless com AWS Lambda\n- Gerenciar identidades e permissões com IAM\n- Trabalhar com bancos de dados gerenciados no RDS\n- Monitorar aplicações com CloudWatch\n- Estruturar arquiteturas seguras, escaláveis e de alta disponibilidade\n\n---\n\n#### Para quem é este curso?\n\n- Desenvolvedores que querem aprender cloud computing na prática\n- Profissionais que desejam obter certificações AWS\n- Estudantes que querem trabalhar com infraestrutura moderna\n- Times que precisam migrar ou evoluir sua infraestrutura para a nuvem\n\n---\n\n#### Resultado esperado\n\nAo final do curso, você será capaz de arquitetar, implantar e gerenciar soluções completas na AWS, com segurança, escalabilidade e as melhores práticas utilizadas por empresas no mundo todo.\n','Todos os níveis','18.0',25,349.99,'Português','Rafael Oliveira',4100,'v1779370131/aws-image_u3esdn.jpg','2026-05-01 00:00:00.000000','aws-completo');
